/* ===========================
   NOIR — Dark Ecommerce Theme
   =========================== */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-base: #0c0c0e;
  --bg-surface: #141416;
  --bg-elevated: #1c1c1f;
  --bg-hover: #242428;
  --border: #2a2a2e;
  --border-subtle: #1e1e22;

  --text-primary: #f0f0f2;
  --text-secondary: #9a9aa8;
  --text-muted: #5a5a68;

  --gold: #c9a84c;
  --gold-light: #e2c070;
  --gold-dark: #9a7a30;

  --accent-red: #e05252;
  --accent-green: #4caf7a;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;

  --shadow-card: 0 4px 24px rgba(0,0,0,0.45);
  --shadow-hover: 0 8px 40px rgba(0,0,0,0.6);
  --shadow-gold: 0 0 24px rgba(201,168,76,0.2);

  --transition: 0.22s ease;
  --font-sans: 'Inter', system-ui, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;
}

/* ---- Base ---- */
html {
  scroll-behavior: smooth;
  overflow-wrap: anywhere;
}

body {
  background-color: var(--bg-base);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: inherit;
  text-decoration: none;
}

ul { list-style: none; }

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ---- Skip link ---- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: 0.6rem 1.2rem;
  background: var(--gold);
  color: #000;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: top 0.15s;
}
.skip-link:focus {
  top: 1rem;
  outline: 2px solid var(--gold-light);
  outline-offset: 2px;
}

/* ---- Container ---- */
.container {
  width: min(1280px, 100%);
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 2.5rem);
}

/* ===========================
   HEADER / NAV
   =========================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(12, 12, 14, 0.88);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--border-subtle);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  height: 68px;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  flex-shrink: 0;
}

.logo-mark {
  width: 32px;
  height: 32px;
  background: var(--gold);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-mark svg {
  fill: #000;
}

.logo-text {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--text-primary);
}

/* Primary nav */
.primary-nav {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.primary-nav a {
  padding: 0.45rem 0.9rem;
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}

.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.primary-nav a:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  color: var(--text-primary);
}

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}

.icon-btn:hover {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.icon-btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  color: var(--text-primary);
}

.cart-badge {
  position: absolute;
  top: 5px;
  right: 5px;
  min-width: 17px;
  height: 17px;
  padding-inline: 4px;
  background: var(--gold);
  color: #000;
  font-size: 0.65rem;
  font-weight: 700;
  border-radius: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1.2rem;
  background: var(--gold);
  color: #000;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  border-radius: var(--radius-sm);
  transition: background var(--transition), box-shadow var(--transition), transform 0.1s;
}

.btn-primary:hover {
  background: var(--gold-light);
  box-shadow: var(--shadow-gold);
}

.btn-primary:active { transform: scale(0.98); }

.btn-primary:focus-visible {
  outline: 2px solid var(--gold-light);
  outline-offset: 2px;
}

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}

.menu-toggle:hover { background: var(--bg-elevated); color: var(--text-primary); }
.menu-toggle:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

.menu-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
  transition: transform 0.2s, opacity 0.2s;
}

.menu-toggle[aria-expanded="true"] span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.menu-toggle[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.menu-toggle[aria-expanded="true"] span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* Mobile nav drawer */
.mobile-nav {
  display: none;
  flex-direction: column;
  gap: 0.25rem;
  padding: 1rem 0 1.25rem;
  border-top: 1px solid var(--border-subtle);
}

.mobile-nav.open { display: flex; }

.mobile-nav a {
  padding: 0.6rem 0.5rem;
  font-size: 0.925rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}

.mobile-nav a:hover { color: var(--text-primary); background: var(--bg-elevated); }
.mobile-nav a:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

/* ===========================
   ANNOUNCEMENT BAR
   =========================== */
.announcement-bar {
  background: var(--gold);
  color: #000;
  text-align: center;
  padding: 0.55rem 1rem;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.announcement-bar a {
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.announcement-bar a:focus-visible {
  outline: 2px solid #000;
  outline-offset: 2px;
  border-radius: 2px;
}

/* ===========================
   HERO
   =========================== */
.hero {
  position: relative;
  min-height: min(88vh, 720px);
  display: flex;
  align-items: flex-end;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 65% 40%, rgba(201,168,76,0.07) 0%, transparent 60%),
    linear-gradient(160deg, #0c0c0e 0%, #161620 50%, #1a1012 100%);
  z-index: 0;
}

/* Decorative geometric */
.hero-bg::before {
  content: '';
  position: absolute;
  top: 8%;
  right: 6%;
  width: min(480px, 50vw);
  height: min(480px, 50vw);
  border: 1px solid rgba(201,168,76,0.12);
  border-radius: 50%;
}

.hero-bg::after {
  content: '';
  position: absolute;
  top: 14%;
  right: 10%;
  width: min(360px, 38vw);
  height: min(360px, 38vw);
  border: 1px solid rgba(201,168,76,0.08);
  border-radius: 50%;
}

.hero-product-visual {
  position: absolute;
  top: 0;
  right: 0;
  width: min(52%, 640px);
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
}

.hero-product-card {
  width: 280px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-hover), 0 0 80px rgba(201,168,76,0.08);
  transform: rotate(3deg) translateY(-20px);
  transition: transform 0.5s ease;
}

.hero-product-card:hover { transform: rotate(1deg) translateY(-28px); }

.hero-product-image {
  height: 300px;
  background: linear-gradient(135deg, #1e1a2a 0%, #2a1f18 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
}

.hero-product-info {
  padding: 1.2rem;
}

.hero-product-info .product-name {
  font-family: var(--font-serif);
  font-size: 1rem;
  margin-bottom: 0.3rem;
}

.hero-product-info .product-price {
  color: var(--gold);
  font-weight: 700;
  font-size: 1.1rem;
}

.hero-content {
  position: relative;
  z-index: 2;
  padding-block: clamp(3rem, 8vh, 6rem);
  max-width: 560px;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 1rem;
}

.hero-eyebrow::before {
  content: '';
  display: block;
  width: 24px;
  height: 1px;
  background: var(--gold);
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.8rem, 6vw, 5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.01em;
  margin-bottom: 1.25rem;
  color: var(--text-primary);
}

.hero-title em {
  font-style: italic;
  color: var(--gold-light);
}

.hero-description {
  font-size: 1.05rem;
  color: var(--text-secondary);
  max-width: 420px;
  margin-bottom: 2rem;
  line-height: 1.7;
}

.hero-cta-group {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
}

.btn-outline {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1.2rem;
  background: transparent;
  color: var(--text-primary);
  font-size: 0.875rem;
  font-weight: 500;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), background var(--transition);
}

.btn-outline:hover { border-color: var(--gold); background: rgba(201,168,76,0.07); }
.btn-outline:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.btn-outline:active { transform: scale(0.98); }

.hero-stats {
  display: flex;
  gap: 2.5rem;
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border-subtle);
}

.hero-stat-value {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-primary);
}

.hero-stat-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-top: 0.15rem;
}

/* ===========================
   SECTION COMMON
   =========================== */
section {
  padding-block: clamp(3rem, 6vw, 5rem);
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: clamp(1.5rem, 3vw, 2.5rem);
  flex-wrap: wrap;
}

.section-label {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 0.4rem;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.6rem, 3.5vw, 2.4rem);
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-primary);
}

.section-link {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--gold);
  white-space: nowrap;
  transition: gap var(--transition);
}

.section-link:hover { gap: 0.65rem; }
.section-link:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; border-radius: 3px; }

/* ===========================
   CATEGORY STRIP
   =========================== */
.categories-section {
  padding-block: 2rem 0;
  border-bottom: 1px solid var(--border-subtle);
}

.categories-strip {
  display: flex;
  gap: 0.75rem;
  overflow-x: auto;
  padding-bottom: 1rem;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.categories-strip::-webkit-scrollbar { display: none; }

.category-chip {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1.1rem;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
  white-space: nowrap;
}

.category-chip:hover,
.category-chip[aria-pressed="true"] {
  color: var(--text-primary);
  border-color: var(--gold);
  background: rgba(201,168,76,0.08);
}

.category-chip:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

.category-chip .chip-icon { font-size: 1rem; }

/* ===========================
   PRODUCT CARDS
   =========================== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(260px, 100%), 1fr));
  gap: clamp(1rem, 2.5vw, 1.5rem);
}

.product-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
  border-color: var(--border);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-elevated);
  overflow: hidden;
}

.product-image-wrap .product-emoji {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4.5rem;
  transition: transform 0.4s ease;
}

.product-card:hover .product-emoji { transform: scale(1.08); }

.product-badges {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.6rem;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border-radius: 4px;
}

.badge-new { background: var(--gold); color: #000; }
.badge-sale { background: var(--accent-red); color: #fff; }
.badge-bestseller { background: rgba(255,255,255,0.12); color: var(--text-primary); backdrop-filter: blur(6px); }

/* Quick-add button */
.product-quick-add {
  position: absolute;
  bottom: 0.75rem;
  left: 50%;
  transform: translateX(-50%) translateY(calc(100% + 8px));
  white-space: nowrap;
  padding: 0.5rem 1rem;
  background: var(--gold);
  color: #000;
  font-size: 0.78rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: transform 0.22s ease, opacity 0.22s ease;
  opacity: 0;
  pointer-events: none;
}

.product-card:hover .product-quick-add,
.product-card:focus-within .product-quick-add {
  transform: translateX(-50%) translateY(0);
  opacity: 1;
  pointer-events: auto;
}

.product-quick-add:focus-visible {
  outline: 2px solid var(--gold-light);
  outline-offset: 2px;
}

/* Wishlist */
.product-wishlist {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  width: 34px;
  height: 34px;
  background: rgba(12,12,14,0.7);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  backdrop-filter: blur(6px);
  transition: color var(--transition), background var(--transition);
}

.product-wishlist:hover { color: var(--accent-red); background: rgba(224,82,82,0.15); }
.product-wishlist[aria-pressed="true"] { color: var(--accent-red); }
.product-wishlist:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

.product-body {
  padding: 1rem 1.1rem 1.1rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.product-category {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 0.3rem;
}

.product-name {
  font-family: var(--font-serif);
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.4rem;
  line-height: 1.3;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 0.6rem;
}

.stars {
  display: flex;
  gap: 1px;
  color: var(--gold);
  font-size: 0.75rem;
}

.rating-count {
  font-size: 0.72rem;
  color: var(--text-muted);
}

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border-subtle);
  gap: 0.5rem;
}

.product-price-wrap {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.product-price {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-primary);
}

.product-price-original {
  font-size: 0.78rem;
  color: var(--text-muted);
  text-decoration: line-through;
}

.product-price.on-sale { color: var(--gold); }

.add-to-cart-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  background: var(--bg-hover);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: background var(--transition), color var(--transition);
  flex-shrink: 0;
}

.add-to-cart-btn:hover { background: var(--gold); color: #000; }
.add-to-cart-btn:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.add-to-cart-btn:active { transform: scale(0.93); }

/* ===========================
   DEALS SECTION
   =========================== */
.deals-section {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

/* Hero deal card */
.deal-card-hero {
  grid-row: span 2;
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 480px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  background: linear-gradient(135deg, #1a0e2e 0%, #2a1018 100%);
  border: 1px solid var(--border);
  transition: box-shadow var(--transition);
}

.deal-card-hero:hover { box-shadow: var(--shadow-hover); }

.deal-bg-emoji {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9rem;
  opacity: 0.18;
  pointer-events: none;
  user-select: none;
}

.deal-card-content {
  position: relative;
  z-index: 1;
  padding: 1.75rem;
  background: linear-gradient(to top, rgba(10,8,18,0.95) 0%, rgba(10,8,18,0.7) 60%, transparent 100%);
}

.deal-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.3rem 0.8rem;
  background: var(--gold);
  color: #000;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: 100px;
  margin-bottom: 0.85rem;
}

.deal-title {
  font-family: var(--font-serif);
  font-size: clamp(1.4rem, 2.5vw, 1.9rem);
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.4rem;
  line-height: 1.25;
}

.deal-subtitle {
  font-size: 0.88rem;
  color: var(--text-secondary);
  margin-bottom: 1.1rem;
}

/* Countdown */
.countdown {
  display: flex;
  gap: 0.6rem;
  margin-bottom: 1.2rem;
  flex-wrap: wrap;
}

.countdown-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: rgba(255,255,255,0.07);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0.5rem 0.7rem;
  min-width: 52px;
}

.countdown-value {
  font-size: 1.35rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--gold-light);
}

.countdown-label {
  font-size: 0.6rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

.deal-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.65rem 1.4rem;
  background: var(--gold);
  color: #000;
  font-size: 0.875rem;
  font-weight: 700;
  border-radius: var(--radius-sm);
  transition: background var(--transition), box-shadow var(--transition);
}

.deal-cta:hover { background: var(--gold-light); box-shadow: var(--shadow-gold); }
.deal-cta:focus-visible { outline: 2px solid var(--gold-light); outline-offset: 2px; }
.deal-cta:active { transform: scale(0.97); }

/* Smaller deal cards */
.deal-card-small {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  align-items: flex-end;
  min-height: 220px;
  border: 1px solid var(--border);
  background: var(--bg-elevated);
  transition: transform var(--transition), box-shadow var(--transition);
  cursor: pointer;
}

.deal-card-small:hover { transform: translateY(-3px); box-shadow: var(--shadow-hover); }
.deal-card-small:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

.deal-card-small .deal-bg-emoji {
  font-size: 6rem;
  opacity: 0.22;
}

.deal-card-small .deal-card-content {
  padding: 1.25rem;
  background: linear-gradient(to top, rgba(10,10,14,0.95) 0%, transparent 100%);
  width: 100%;
}

.deal-card-small .deal-badge {
  font-size: 0.68rem;
  padding: 0.2rem 0.65rem;
}

.deal-card-small .deal-title {
  font-size: 1.05rem;
}

.deal-discount {
  font-family: var(--font-serif);
  font-size: 2rem;
  font-weight: 700;
  color: var(--gold);
  line-height: 1;
}

/* ===========================
   FEATURED BRANDS
   =========================== */
.brands-section {
  padding-block: 2.5rem;
  border-bottom: 1px solid var(--border-subtle);
}

.brands-label {
  text-align: center;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.brands-strip {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.5rem 2.5rem;
}

.brand-name {
  font-family: var(--font-serif);
  font-size: clamp(0.9rem, 2vw, 1.15rem);
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  transition: color var(--transition);
}

.brand-name:hover { color: var(--text-secondary); }

/* ===========================
   EDITORIAL SECTION
   =========================== */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.editorial-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition), box-shadow var(--transition);
}

.editorial-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-hover); }
.editorial-card:focus-within { border-color: var(--border); }

.editorial-image {
  aspect-ratio: 16/10;
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  overflow: hidden;
  position: relative;
}

.editorial-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 50%, rgba(10,10,14,0.6) 100%);
}

.editorial-content {
  padding: 1.25rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.editorial-tag {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.65rem;
  background: rgba(201,168,76,0.12);
  color: var(--gold);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: 4px;
  margin-bottom: 0.7rem;
  width: fit-content;
}

.editorial-title {
  font-family: var(--font-serif);
  font-size: 1.1rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 0.5rem;
  color: var(--text-primary);
}

.editorial-title a {
  transition: color var(--transition);
}

.editorial-title a:hover { color: var(--gold-light); }
.editorial-title a:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; border-radius: 2px; }

.editorial-excerpt {
  font-size: 0.85rem;
  color: var(--text-secondary);
  line-height: 1.6;
  flex: 1;
}

.editorial-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 1rem;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border-subtle);
  font-size: 0.75rem;
  color: var(--text-muted);
}

.editorial-author {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.author-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--bg-hover);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
}

/* ===========================
   NEWSLETTER SECTION
   =========================== */
.newsletter-section {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2.5rem;
  align-items: center;
}

.newsletter-heading {
  font-family: var(--font-serif);
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 700;
  margin-bottom: 0.6rem;
  line-height: 1.25;
}

.newsletter-desc {
  color: var(--text-secondary);
  font-size: 0.95rem;
}

.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.newsletter-input-row {
  display: flex;
  gap: 0.5rem;
}

.input-text {
  flex: 1;
  min-width: 0;
  padding: 0.65rem 1rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.9rem;
  font-family: inherit;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.input-text::placeholder { color: var(--text-muted); }

.input-text:focus {
  outline: none;
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(201,168,76,0.15);
}

.newsletter-consent {
  display: flex;
  gap: 0.6rem;
  align-items: flex-start;
  font-size: 0.78rem;
  color: var(--text-muted);
  cursor: pointer;
  line-height: 1.5;
}

.newsletter-consent input[type="checkbox"] {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  margin-top: 1px;
  accent-color: var(--gold);
  cursor: pointer;
}

.newsletter-consent a { color: var(--gold); }
.newsletter-consent a:hover { text-decoration: underline; }

.newsletter-perks {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
  margin-top: 0.75rem;
}

.perk {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.78rem;
  color: var(--text-muted);
}

.perk-icon { color: var(--gold); font-size: 0.9rem; }

/* ===========================
   TOAST NOTIFICATION
   =========================== */
.toast-region {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 500;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  pointer-events: none;
}

.toast {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.8rem 1.1rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-hover);
  font-size: 0.875rem;
  color: var(--text-primary);
  pointer-events: auto;
  animation: toast-in 0.3s ease forwards;
  max-width: 320px;
}

.toast.removing { animation: toast-out 0.25s ease forwards; }

.toast-icon { font-size: 1.1rem; flex-shrink: 0; }

.toast-close {
  margin-left: auto;
  color: var(--text-muted);
  border-radius: 4px;
  padding: 2px;
  font-size: 1rem;
  transition: color var(--transition);
}

.toast-close:hover { color: var(--text-primary); }
.toast-close:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

@keyframes toast-in {
  from { transform: translateX(110%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

@keyframes toast-out {
  from { transform: translateX(0); opacity: 1; }
  to { transform: translateX(110%); opacity: 0; }
}

/* ===========================
   FOOTER
   =========================== */
.site-footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  padding-top: clamp(2.5rem, 5vw, 4rem);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 2.5rem 2rem;
}

.footer-brand p {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: 0.85rem;
  max-width: 240px;
  line-height: 1.65;
}

.footer-socials {
  display: flex;
  gap: 0.5rem;
  margin-top: 1.25rem;
}

.social-btn {
  width: 36px;
  height: 36px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  color: var(--text-muted);
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}

.social-btn:hover { color: var(--text-primary); border-color: var(--gold); background: rgba(201,168,76,0.08); }
.social-btn:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

.footer-col-title {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-secondary);
  margin-bottom: 1rem;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.footer-links a {
  font-size: 0.875rem;
  color: var(--text-muted);
  transition: color var(--transition);
}

.footer-links a:hover { color: var(--text-primary); }
.footer-links a:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; border-radius: 2px; }

.footer-bottom {
  margin-top: 3rem;
  padding-block: 1.25rem;
  border-top: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.footer-bottom-text {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.payment-methods {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.payment-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 24px;
  padding: 0 0.4rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 4px;
  font-size: 0.65rem;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

/* ===========================
   RESPONSIVE
   =========================== */
@media (max-width: 1024px) {
  .hero-product-visual { display: none; }
  .editorial-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .primary-nav { display: none; }
  .menu-toggle { display: flex; }

  .deals-grid { grid-template-columns: 1fr; }
  .deal-card-hero { grid-row: span 1; }

  .newsletter-inner { grid-template-columns: 1fr; gap: 1.5rem; }

  .hero-stats { gap: 1.5rem; }
}

@media (max-width: 600px) {
  .editorial-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .hero-stats { flex-wrap: wrap; gap: 1rem; }
  .newsletter-input-row { flex-direction: column; }
}

/* ===========================
   REDUCED MOTION
   =========================== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ===========================
   FORCED COLORS
   =========================== */
@media (forced-colors: active) {
  .btn-primary,
  .deal-cta,
  .badge-new,
  .badge-sale { background: ButtonText; color: ButtonFace; forced-color-adjust: none; }
  .product-card,
  .editorial-card,
  .deal-card-hero,
  .deal-card-small { border-color: ButtonText; }
  .cart-badge { background: Highlight; color: HighlightText; }
  .icon-btn,
  .add-to-cart-btn,
  .social-btn { border: 1px solid ButtonText; }
  .skip-link { background: ButtonText; color: ButtonFace; }
}

