   NOIR — Dark Ecommerce Theme
   =========================== */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-base: #0c0c0e;
  --bg-surface: #141416;
  --bg-elevated: #1c1c1f;
  --bg-hover: #242428;
  --border: #2a2a2e;
  --border-subtle: #1e1e22;

  --text-primary: #f0f0f2;
  --text-secondary: #9a9aa8;
  --text-muted: #5a5a68;

  --gold: #c9a84c;
  --gold-light: #e2c070;
  --gold-dark: #9a7a30;

  --accent-red: #e05252;
  --accent-green: #4caf7a;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;

  --shadow-card: 0 4px 24px rgba(0,0,0,0.45);
  --shadow-hover: 0 8px 40px rgba(0,0,0,0.6);
  --shadow-gold: 0 0 24px rgba(201,168,76,0.2);

  --transition: 0.22s ease;
  --font-sans: 'Inter', system-ui, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;
}

/* ---- Base ---- */
html {
  scroll-behavior: smooth;
  overflow-wrap: anywhere;
}

body {
  background-color: var(--bg-base);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: inherit;
  text-decoration: none;
}

ul { list-style: none; }

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ---- Skip link ---- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: 0.6rem 1.2rem;
  background: var(--gold);
  color: #000;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: top 0.15s;
}
.skip-link:focus {
  top: 1rem;
  outline: 2px solid var(--gold-light);
  outline-offset: 2px;
}

/* ---- Container ---- */
.container {
  width: min(1280px, 100%);
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 2.5rem);
}

/* ===========================
   HEADER / NAV
   =========================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(12, 12, 14, 0.88);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--border-subtle);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  height: 68px;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  flex-shrink: 0;
}

.logo-mark {
  width: 32px;
  height: 32px;
  background: var(--gold);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-mark svg {
  fill: #000;
}

.logo-text {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--text-primary);
}

/* Primary nav */
.primary-nav {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.primary-nav a {
  padding: 0.45rem 0.9rem;
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}

.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.primary-nav a:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  color: var(--text-primary);
}

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}

.icon-btn:hover {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.icon-btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  color: var(--text-primary);
}

.cart-badge {
  position: absolute;
  top: 5px;
  right: 5px;
  min-width: 17px;
  height: 17px;
  padding-inline: 4px;
  background: var(--gold);
  color: #000;
  font-size: 0.65rem;
  font-weight: 700;
  border-radius: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1.2rem;
  background: var(--gold);
  color: #000;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  border-radius: var(--radius-sm);
  transition: background var(--transition), box-shadow var(--transition), transform 0.1s;
}

.btn-primary:hover {
  background: var(--gold-light);
  box-shadow: var(--shadow-gold);
}

.btn-primary:active { transform: scale(0.98); }

.btn-primary:focus-visible {
  outline: 2px solid var(--gold-light);
  outline-offset: 2px;
}

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}

.menu-toggle:hover { background: var(--bg-elevated); color: var(--text-primary); }
.menu-toggle:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

.menu-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
  transition: transform 0.2s, opacity 0.2s;
}

.menu-toggle[aria-expanded="true"] span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.menu-toggle[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.menu-toggle[aria-expanded="true"] span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* Mobile nav drawer */
.mobile-nav {
  display: none;
  flex-direction: column;
  gap: 0.25rem;
  padding: 1rem 0 1.25rem;
  border-top: 1px solid var(--border-subtle);
}

.mobile-nav.open { display: flex; }

.mobile-nav a {
  padding: 0.6rem 0.5rem;
  font-size: 0.925rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}

.mobile-nav a:hover { color: var(--text-primary); background: var(--bg-elevated); }
.mobile-nav a:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

/* ===========================
   ANNOUNCEMENT BAR
   =========================== */
.announcement-bar {
  background: var(--gold);
  color: #000;
  text-align: center;
  padding: 0.55rem 1rem;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.announcement-bar a {
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.announcement-bar a:focus-visible {
  outline: 2px solid #000;
  outline-offset: 2px;
  border-radius: 2px;
}

/* ===========================
   HERO
   =========================== */
.hero {
  position: relative;
  min-height: min(88vh, 720px);
  display: flex;
  align-items: flex-end;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 65% 40%, rgba(201,168,76,0.07) 0%, transparent 60%),
    linear-gradient(160deg, #0c0c0e 0%, #161620 50%, #1a1012 100%);
  z-index: 0;
}

/* Decorative geometric */
.hero-bg::before {
  content: '';
  position: absolute;
  top: 8%;
  right: 6%;
  width: min(480px, 50vw);
  height: min(480px, 50vw);
  border: 1px solid rgba(201,168,76,0.12);
  border-radius: 50%;
}

.hero-bg::after {
  content: '';
  position: absolute;
  top: 14%;
  right: 10%;
  width: min(360px, 38vw);
  height: min(360px, 38vw);
  border: 1px solid rgba(201,168,76,0.08);
  border-radius: 50%;
}

.hero-product-visual {
  position: absolute;
  top: 0;
  right: 0;
  width: min(52%, 640px);
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
}

.hero-product-card {
  width: 280px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-hover), 0 0 80px rgba(201,168,76,0.08);
  transform: rotate(3deg) translateY(-20px);
  transition: transform 0.5s ease;
}

.hero-product-card:hover { transform: rotate(1deg) translateY(-28px); }

.hero-product-image {
  height: 300px;
  background: linear-gradient(135deg, #1e1a2a 0%, #2a1f18 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
}

.hero-product-info {
  padding: 1.2rem;
}

.hero-product-info .product-name {
  font-family: var(--font-serif);
  font-size: 1rem;
  margin-bottom: 0.3rem;
}

.hero-product-info .product-price {
  color: var(--gold);
  font-weight: 700;
  font-size: 1.1rem;
}

.hero-content {
  position: relative;
  z-index: 2;
  padding-block: clamp(3rem, 8vh, 6rem);
  max-width: 560px;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 1rem;
}

.hero-eyebrow::before {
  content: '';
  display: block;
  width: 24px;
  height: 1px;
  background: var(--gold);
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.8rem, 6vw, 5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.01em;
  margin-bottom: 1.25rem;
  color: var(--text-primary);
}

.hero-title em {
  font-style: italic;
  color: var(--gold-light);
}

.hero-description {
  font-size: 1.05rem;
  color: var(--text-secondary);
  max-width: 420px;
  margin-bottom: 2rem;
  line-height: 1.7;
}

.hero-cta-group {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
}

.btn-outline {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1.2rem;
  background: transparent;
  color: var(--text-primary);
  font-size: 0.875rem;
  font-weight: 500;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), background var(--transition);
}

.btn-outline:hover { border-color: var(--gold); background: rgba(201,168,76,0.07); }
.btn-outline:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.btn-outline:active { transform: scale(0.98); }

.hero-stats {
  display: flex;
  gap: 2.5rem;
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border-subtle);
}

.hero-stat-value {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-primary);
}

.hero-stat-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-top: 0.15rem;
}

/* ===========================
   SECTION COMMON
   =========================== */
section {
  padding-block: clamp(3rem, 6vw, 5rem);
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: clamp(1.5rem, 3vw, 2.5rem);
  flex-wrap: wrap;
}

.section-label {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 0.4rem;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.6rem, 3.5vw, 2.4rem);
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-primary);
}

.section-link {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--gold);
  white-space: nowrap;
  transition: gap var(--transition);
}

.section-link:hover { gap: 0.65rem; }
.section-link:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; border-radius: 3px; }

/* ===========================
   CATEGORY STRIP
   =========================== */
.categories-section {
  padding-block: 2rem 0;
  border-bottom: 1px solid var(--border-subtle);
}

.categories-strip {
  display: flex;
  gap: 0.75rem;
  overflow-x: auto;
  padding-bottom: 1rem;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.categories-strip::-webkit-scrollbar { display: none; }

.category-chip {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1.1rem;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
  white-space: nowrap;
}

.category-chip:hover,
.category-chip[aria-pressed="true"] {
  color: var(--text-primary);
  border-color: var(--gold);
  background: rgba(201,168,76,0.08);
}

.category-chip:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

.category-chip .chip-icon { font-size: 1rem; }

/* ===========================
   PRODUCT CARDS
   =========================== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(260px, 100%), 1fr));
  gap: clamp(1rem, 2.5vw, 1.5rem);
}

.product-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
  border-color: var(--border);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-elevated);
  overflow: hidden;
}

.product-image-wrap .product-emoji {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4.5rem;
  transition: transform 0.4s ease;
}

.product-card:hover .product-emoji { transform: scale(1.08); }

.product-badges {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.6rem;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border-radius: 4px;
}

.badge-new { background: var(--gold); color: #000; }
.badge-sale { background: var(--accent-red); color: #fff; }
.badge-bestseller { background: rgba(255,255,255,0.12); color: var(--text-primary); backdrop-filter: blur(6px); }

/* Quick-add button */
.product-quick-add {
  position: absolute;
  bottom: 0.75rem;
  left: 50%;
  transform: translateX(-50%) translateY(calc(100% + 8px));
  white-space: nowrap;
  padding: 0.5rem 1rem;
  background: var(--gold);
  color: #000;
  font-size: 0.78rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: transform 0.22s ease, opacity 0.22s ease;
  opacity: 0;
  pointer-events: none;
}

.product-card:hover .product-quick-add,
.product-card:focus-within .product-quick-add {
  transform: translateX(-50%) translateY(0);
  opacity: 1;
  pointer-events: auto;
}

.product-quick-add:focus-visible {
  outline: 2px solid var(--gold-light);
  outline-offset: 2px;
}

/* Wishlist */
.product-wishlist {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  width: 34px;
  height: 34px;
  background: rgba(12,12,14,0.7);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  backdrop-filter: blur(6px);
  transition: color var(--transition), background var(--transition);
}

.product-wishlist:hover { color: var(--accent-red); background: rgba(224,82,82,0.15); }
.product-wishlist[aria-pressed="true"] { color: var(--accent-red); }
.product-wishlist:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

.product-body {
  padding: 1rem 1.1rem 1.1rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.product-category {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 0.3rem;
}

.product-name {
  font-family: var(--font-serif);
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.4rem;
  line-height: 1.3;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 0.6rem;
}

.stars {
  display: flex;
  gap: 1px;
  color: var(--gold);
  font-size: 0.75rem;
}

.rating-count {
  font-size: 0.72rem;
  color: var(--text-muted);
}

