+.deal-card-hero:hover { box-shadow: var(--shadow-hover); }
+
+.deal-bg-emoji {
+  position: absolute;
+  inset: 0;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 9rem;
+  opacity: 0.18;
