+  padding-block: 2.5rem;
+  border-bottom: 1px solid var(--border-subtle);
+}
+
+.brands-label {
+  text-align: center;
+  font-size: 0.7rem;
+  font-weight: 600;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
