(function () {
  'use strict';

  /* ---- Cart state ---- */
  let cartCount = 0;

  /* ---- DOM refs ---- */
  const cartBadge = document.querySelector('.cart-badge');
  const menuToggle = document.querySelector('.menu-toggle');
  const mobileNav = document.getElementById('mobile-nav');
  const toastRegion = document.querySelector('.toast-region');
  const countdownEls = {
    h: document.getElementById('cd-hours'),
    m: document.getElementById('cd-minutes'),
    s: document.getElementById('cd-seconds'),
  };

  /* ===========================
     Cart badge
     =========================== */
  function updateCartBadge(n) {
    cartCount = n;
    if (!cartBadge) return;
    cartBadge.textContent = n;
    cartBadge.hidden = n === 0;
    cartBadge.setAttribute('aria-label', `${n} item${n !== 1 ? 's' : ''} in cart`);
  }

  updateCartBadge(cartCount);

  /* ===========================
     Add-to-cart handler
     =========================== */
  function handleAddToCart(btn) {
    const card = btn.closest('[data-product]');
    const name = card ? card.dataset.product : 'Item';
    updateCartBadge(cartCount + 1);
    showToast('🛍️', `<strong>${name}</strong> added to your bag`);
  }

  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-action="add-to-cart"]');
    if (btn) { e.preventDefault(); handleAddToCart(btn); }
  });

  /* ===========================
     Wishlist toggle
     =========================== */
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-action="wishlist"]');
    if (!btn) return;
    const pressed = btn.getAttribute('aria-pressed') === 'true';
    btn.setAttribute('aria-pressed', String(!pressed));
    const card = btn.closest('[data-product]');
    const name = card ? card.dataset.product : 'Item';
    if (!pressed) {
      showToast('♥', `<strong>${name}</strong> saved to wishlist`);
    }
  });

  /* ===========================
     Category chips
     =========================== */
  document.addEventListener('click', (e) => {
    const chip = e.target.closest('[data-action="filter"]');
    if (!chip) return;
    const group = chip.closest('.categories-strip');
    if (group) {
      group.querySelectorAll('[data-action="filter"]').forEach(c => {
        c.setAttribute('aria-pressed', 'false');
      });
    }
    chip.setAttribute('aria-pressed', 'true');
  });

  /* ===========================
     Mobile nav
     =========================== */
  if (menuToggle && mobileNav) {
    menuToggle.addEventListener('click', () => {
      const open = menuToggle.getAttribute('aria-expanded') === 'true';
      menuToggle.setAttribute('aria-expanded', String(!open));
      mobileNav.classList.toggle('open', !open);
    });

    // Close on Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && menuToggle.getAttribute('aria-expanded') === 'true') {
        menuToggle.setAttribute('aria-expanded', 'false');
        mobileNav.classList.remove('open');
        menuToggle.focus();
      }
    });
  }

  /* ===========================
     Countdown timer
     =========================== */
  // Target: 18 hours from now (deal ends tonight)
  const TARGET = Date.now() + 18 * 60 * 60 * 1000 + 32 * 60 * 1000 + 14 * 1000;

  function updateCountdown() {
    const diff = Math.max(0, TARGET - Date.now());
    const h = Math.floor(diff / 3_600_000);
    const m = Math.floor((diff % 3_600_000) / 60_000);
    const s = Math.floor((diff % 60_000) / 1_000);

    const pad = n => String(n).padStart(2, '0');

    if (countdownEls.h) countdownEls.h.textContent = pad(h);
    if (countdownEls.m) countdownEls.m.textContent = pad(m);
    if (countdownEls.s) countdownEls.s.textContent = pad(s);
  }

  updateCountdown();
  setInterval(updateCountdown, 1000);

  /* ===========================
     Toast system
     =========================== */
  function showToast(icon, message) {
    if (!toastRegion) return;

    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.setAttribute('role', 'status');
    toast.setAttribute('aria-live', 'polite');
    toast.innerHTML = `
      <span class="toast-icon" aria-hidden="true">${icon}</span>
      <span class="toast-msg">${message}</span>
      <button class="toast-close" aria-label="Dismiss notification">✕</button>
    `;

    const closeBtn = toast.querySelector('.toast-close');
    closeBtn.addEventListener('click', () => removeToast(toast));

    toastRegion.appendChild(toast);

    const timer = setTimeout(() => removeToast(toast), 4000);
    toast._timer = timer;
  }

  function removeToast(toast) {
    clearTimeout(toast._timer);
    toast.classList.add('removing');
    toast.addEventListener('animationend', () => toast.remove(), { once: true });
  }

  /* ===========================
     Newsletter form
     =========================== */
  const newsletterForm = document.querySelector('.newsletter-form');
  if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const emailInput = newsletterForm.querySelector('input[type="email"]');
      const consentCheck = newsletterForm.querySelector('input[type="checkbox"]');
      let valid = true;

      // Clear previous errors
      newsletterForm.querySelectorAll('[aria-describedby]').forEach(el => {
        const errId = el.getAttribute('aria-describedby');
        const errEl = document.getElementById(errId);
        if (errEl) errEl.textContent = '';
        el.removeAttribute('aria-invalid');
      });

      if (!emailInput.value.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailInput.value)) {
        setFieldError(emailInput, 'email-error', 'Please enter a valid email address.');
        valid = false;
      }

      if (!consentCheck.checked) {
        setFieldError(consentCheck, 'consent-error', 'You must agree to receive emails.');
        valid = false;
      }

      if (!valid) {
        // Focus first invalid
        const firstInvalid = newsletterForm.querySelector('[aria-invalid="true"]');
        if (firstInvalid) firstInvalid.focus();
        return;
      }

      showToast('✉️', 'You\'re on the list! Check your inbox for a welcome offer.');
      newsletterForm.reset();
    });
  }

  function setFieldError(field, errId, message) {
    field.setAttribute('aria-invalid', 'true');
    field.setAttribute('aria-describedby', errId);
    let errEl = document.getElementById(errId);
    if (!errEl) {
      errEl = document.createElement('span');
      errEl.id = errId;
      errEl.setAttribute('role', 'alert');
      errEl.style.cssText = 'display:block;font-size:0.78rem;color:#e05252;margin-top:0.3rem;';
      field.parentNode.insertBefore(errEl, field.nextSibling);
    }
    errEl.textContent = message;
  }

  /* ===========================
     Scroll-reveal (minimal, no deps)
     =========================== */
  if ('IntersectionObserver' in window) {
    const style = document.createElement('style');
    style.textContent = `
      .reveal { opacity: 0; transform: translateY(16px); transition: opacity 0.5s ease, transform 0.5s ease; }
      .reveal.visible { opacity: 1; transform: translateY(0); }
      @media (prefers-reduced-motion: reduce) { .reveal { opacity: 1 !important; transform: none !important; } }
    `;
    document.head.appendChild(style);

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(({ target, isIntersecting }) => {
        if (isIntersecting) {
          target.classList.add('visible');
          observer.unobserve(target);
        }
      });
    }, { rootMargin: '0px 0px -60px 0px' });

    document.querySelectorAll('.product-card, .editorial-card, .deal-card-small').forEach(el => {
      el.classList.add('reveal');
      observer.observe(el);
    });
  }
})();
