     Countdown timer
     =========================== */
  // Target: 18 hours from now (deal ends tonight)
  const TARGET = Date.now() + 18 * 60 * 60 * 1000 + 32 * 60 * 1000 + 14 * 1000;

  function updateCountdown() {
    const diff = Math.max(0, TARGET - Date.now());
    const h = Math.floor(diff / 3_600_000);
    const m = Math.floor((diff % 3_600_000) / 60_000);
    const s = Math.floor((diff % 60_000) / 1_000);

    const pad = n => String(n).padStart(2, '0');

    if (countdownEls.h) countdownEls.h.textContent = pad(h);
    if (countdownEls.m) countdownEls.m.textContent = pad(m);
    if (countdownEls.s) countdownEls.s.textContent = pad(s);
  }

  updateCountdown();
  setInterval(updateCountdown, 1000);

